INSERT INTO public.clkr_articles (
  slug_key, locale, title, description, category, reading_time, sections, status, sort_order, translation_group_id, published_at
) VALUES (
  'common-law-union',
  'es',
  'Unión Marital de Hecho en Colombia (Common-Law Union)',
  'Qué es la unión marital de hecho, cómo declararla, cuándo nace la sociedad patrimonial y qué cambió con la Ley 2447 de 2025 para uniones solo entre mayores de edad.',
  'Family',
  '22 min',
  '[{"id":"definition","title":"I. Definición jurídica","html":"<p>En el derecho civil colombiano, la <strong>unión marital de hecho</strong> es la comunidad familiar formada por dos mayores de edad que, sin estar casados entre sí, hacen una <strong>comunidad de vida permanente y singular</strong> y se denominan <em>compañeros permanentes</em>.</p>\n<p>En clave didáctica: (1) es el nombre legal de un proyecto de convivencia estable y exclusivo que no es matrimonio civil ni religioso; y (2) es la puerta de entrada a la <strong>sociedad patrimonial entre compañeros permanentes</strong>, cuando se cumplen los umbrales legales de tiempo y capacidad.</p>\n<p>La definición vigente —tras la reforma— exige que ambos sean <strong>mayores de 18 años</strong>. Las uniones tempranas con menores no producen los efectos civiles de la UMH entre adultos; operan las rutas de restablecimiento de derechos.</p>"},{"id":"legal-framework","title":"II. Marco legal","html":"<h3>Constitucional</h3>\n<ul>\n<li><strong>Constitución Política, art. 42</strong> — Familia como núcleo fundamental; igualdad de derechos. Vigente. Texto: <a href=\"http://www.secretariasenado.gov.co/senado/basedoc/constitucion_politica_1991.html\">secretariasenado.gov.co — Constitución</a>.</li>\n</ul>\n<h3>Legal</h3>\n<ul>\n<li><strong>Ley 54 de 1990</strong> — Define la UMH y el régimen patrimonial. Vigente (con reformas). <a href=\"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=30896\">Función Pública — norma.php?i=30896</a>.</li>\n<li><strong>Ley 979 de 2005</strong> — Reforma parcial: declaración por escritura pública, acta de conciliación o sentencia de familia. Vigente. <a href=\"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=30898\">Función Pública — norma.php?i=30898</a> · <a href=\"http://www.secretariasenado.gov.co/senado/basedoc/ley_0979_2005.html\">Senado</a>.</li>\n<li><strong>Ley 2447 de 2025</strong> — Elimina uniones tempranas; reescribe el art. 1 de la Ley 54/1990 (solo mayores de 18) y habilita nulidad de declaraciones con menores. Vigente (13 feb 2025). <a href=\"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=258236\">Función Pública — norma.php?i=258236</a>.</li>\n</ul>\n<h3>Remisiones</h3>\n<ul>\n<li><strong>Código Civil</strong> — Liquidación de sociedad patrimonial por remisión a reglas de sociedad conyugal (confirmar artículos consolidados antes de demandar).</li>\n<li><strong>Juez de familia</strong> — Vía contenciosa con medios ordinarios de prueba (hoy alinear con el Código General del Proceso).</li>\n</ul>"},{"id":"jurisprudence","title":"III. Jurisprudencia","html":"<h3>C-075 de 2007 — Protección patrimonial a parejas del mismo sexo</h3>\n<ul>\n<li><strong>Foro:</strong> Corte Constitucional · <strong>Tipo:</strong> control de constitucionalidad · <strong>Fecha:</strong> 7 de febrero de 2007 · <strong>Alias:</strong> <em>Ley 54/979 también para parejas del mismo sexo</em> · ⏱️ ~45–60 min</li>\n<li><strong>Problema:</strong> Exclusión de parejas homosexuales del régimen de Ley 54/1990 reformada por Ley 979/2005.</li>\n<li><strong>Decisión:</strong> Exequibilidad condicionada: el régimen de protección también aplica a parejas del mismo sexo que cumplan comunidad de vida permanente y singular (incluido el umbral de dos años para la presunción patrimonial según el marco entonces vigente).</li>\n<li><strong>Ratio:</strong> La exclusión era discriminatoria y vulneraba dignidad y libre desarrollo de la personalidad.</li>\n<li><strong>Enlace:</strong> <a href=\"https://www.corteconstitucional.gov.co/relatoria/2007/C-075-07.htm\">corteconstitucional.gov.co/relatoria/2007/C-075-07.htm</a></li>\n</ul>\n<h3>Línea posterior</h3>\n<p>Decisiones posteriores reiteran la lectura inclusiva de <em>compañero/a permanente</em> (p. ej. discusión en <strong>C-151 de 2023</strong>): <a href=\"https://www.corteconstitucional.gov.co/relatoria/2023/c-151-23.htm\">enlace</a>.</p>\n<blockquote>\n<p><strong>Nota de revisión:</strong> Jurisprudencia de la Corte Suprema sobre convivencia sin techo compartido (líneas SC 2024–2025 citadas en fuentes secundarias) debe verificarse en la relatoría oficial antes de usarla — <em>unverified — pending confirmation</em> hasta abrir el PDF del radicado.</p>\n</blockquote>"},{"id":"core-elements","title":"IV. Elementos centrales","html":"<ol>\n<li><strong>Sujetos.</strong> Dos personas <strong>de 18 años o más</strong>, no casadas entre sí.</li>\n<li><strong>Comunidad de vida.</strong> Proyecto compartido: ayuda mutua, integración afectiva y a menudo económica, reconocimiento social.</li>\n<li><strong>Permanencia.</strong> Continuidad en el tiempo; interrupciones por trabajo, estudio o salud pueden caber si el proyecto sigue (caso por caso).</li>\n<li><strong>Singularidad.</strong> Exclusividad: no hay dos UMH simultáneas.</li>\n<li><strong>Sin matrimonio entre ellos.</strong> Matrimonios previos de alguno afectan la vía <strong>patrimonial</strong>, no necesariamente el hecho de la convivencia.</li>\n<li><strong>Declaración.</strong> Escritura pública notarial, acta de conciliación o sentencia de familia (Ley 979).</li>\n<li><strong>Sociedad patrimonial.</strong> Se presume/declara con los supuestos del art. 2 Ley 54 (reformado) — clásicamente <strong>mínimo dos años</strong>, con reglas sobre sociedades conyugales previas.</li>\n<li><strong>Activo social.</strong> Bienes adquiridos durante la unión; quedan por fuera donaciones, herencias y bienes preexistentes (con matices de frutos — confirmar art. 3 tras Ley 2447).</li>\n<li><strong>Disolución y liquidación.</strong> Separación o muerte; vías de acuerdo o demanda.</li>\n<li><strong>Menores.</strong> Tras Ley 2447/2025, no hay efectos de UMH adulta si hay menores; opera restablecimiento de derechos y nulidad de declaraciones.</li>\n</ol>"},{"id":"doctrinal-note","title":"V. Nota doctrinal","html":"<p>La doctrina de familia leyó la UMH como respuesta legislativa a la convivencia informal: proteger al compañero más débil sin imponer el matrimonio. La Ley 54 armó el escudo <strong>patrimonial</strong>; la 979 bajó la fricción probatoria.</p>\n<p>La Corte, con C-075/2007, empujó el estatuto más allá de su molde heterosexual original: no inventó un matrimonio nuevo, <strong>extendió la caja de herramientas patrimoniales</strong>.</p>\n<p>La reforma de 2025 cambia el eje otra vez: de “cómo se prueba” a “quién puede formar una unión con efectos”. Para clientes extranjeros el mensaje es seco: Colombia no trata como UMH productora de patrimonio una relación con menor de edad, y papeles previos en ese sentido son vulnerables a nulidad.</p>"},{"id":"examples","title":"VI. Ejemplos","html":"<h3>Ejemplo 1 — Pareja mixta (extranjero + colombiano)</h3>\n<p>Conviven tres años en Medellín, con exclusividad y reconocimiento social. Firman escritura de UMH y sociedad patrimonial. Compran un apartamento durante la unión. Al separarse, el inmueble se presume activo social sujeto a liquidación, salvo exclusión válida.</p>\n<h3>Ejemplo 2 — Caso corriente</h3>\n<p>Conviven 18 meses y se separan. Puede haber UMH si se prueba permanencia y singularidad, pero no corre aún la presunción patrimonial de dos años. La división cae en títulos ordinarios y aportes.</p>\n<h3>Ejemplo 3 — Caso límite</h3>\n<p>Uno aún tiene sociedad conyugal sin disolver cuando empieza la convivencia. Años después, la <em>sociedad patrimonial</em> sigue bloqueada hasta cumplir la secuencia legal del art. 2 lit. b. Declarar “de una” en notaría sin revisar estado civil es un error caro.</p>"},{"id":"faq","title":"VII. FAQ","html":"<p><strong>1. ¿Basta vivir juntos o hay que escriturar?</strong><br>La convivencia puede existir como hecho. La declaración pública (notaría, conciliación o sentencia) es cómo se <strong>prueba y opera</strong> frente a bancos, pensiones, sucesiones y litigio.</p>\n<p><strong>2. ¿Cuándo nace el 50/50?</strong><br>Cuando se cumplen los supuestos del art. 2 Ley 54 (reformado) — típicamente <strong>dos años</strong>. Puede haber UMH antes de la sociedad patrimonial.</p>\n<p><strong>3. ¿Aplica a parejas del mismo sexo?</strong><br>Sí, por la exequibilidad condicionada de <strong>C-075 de 2007</strong>, si cumplen permanencia y singularidad.</p>\n<p><strong>4. ¿Y si uno sigue casado con otra persona?</strong><br>Puede haber relato fáctico de convivencia, pero la vía patrimonial mira las sociedades previas. Revise antes de firmar paquete notarial.</p>\n<p><strong>5. ¿Y si no compartieron techo todo el tiempo?</strong><br>Hay líneas jurisprudenciales excepcionales. Verifique el radicado exacto de la Corte Suprema antes de apoyarse en ellas.</p>\n<p><strong>6. ¿Qué cambió en 2025?</strong><br>La <strong>Ley 2447 de 2025</strong> limita la UMH con efectos a mayores de 18 y refuerza la respuesta a uniones tempranas, incluida la nulidad.</p>\n<p><strong>7. ¿Es lo mismo que el matrimonio?</strong><br>No. Son instituciones distintas. Hay solapamientos (bienes, algunos beneficios) y diferencias (solemnidades, reconocimiento internacional). El “common-law marriage” extranjero no se traduce 1:1.</p>"},{"id":"glossary","title":"VIII. Glosario","html":"<ul>\n<li><strong>Unión marital de hecho</strong> — Institución legal de convivencia estable y exclusiva entre adultos no casados entre sí.</li>\n<li><strong>Compañero(a) permanente</strong> — Integrante de la UMH.</li>\n<li><strong>Sociedad patrimonial</strong> — Sociedad de bienes presumida entre compañeros al cumplirse umbrales legales.</li>\n<li><strong>Escritura pública</strong> — Instrumento notarial de declaración mutual.</li>\n<li><strong>Acta de conciliación</strong> — Acta en centro de conciliación reconocido.</li>\n<li><strong>Comunidad de vida permanente y singular</strong> — Proyecto de vida compartido, continuo y exclusivo.</li>\n<li><strong>Liquidación</strong> — Reparto de activo y pasivo social.</li>\n<li><strong>Uniones tempranas</strong> — Matrimonio o UMH con menores de 18 (Ley 2447/2025).</li>\n</ul>"},{"id":"translation-notes","title":"IX. Traducción y comentarios","html":"<h3>A. Disonancia terminológica</h3>\n<p>“Common-law marriage” en algunos estados de EE. UU. sugiere matrimonio pleno. La UMH colombiana es una <strong>institución estatutaria de convivencia</strong>, no un matrimonio celebrado sin ceremonia.</p>\n<h3>B. Mapeo comparado</h3>\n<p>A diferencia de muchos estados que abolieron el common-law marriage, Colombia regula activamente la unión informal. A diferencia del <em>PACS</em> francés, la UMH puede nacer de hechos y formalizarse después.</p>\n<h3>C. Decisiones pragmáticas</h3>\n<p>Conservamos los términos en español en la primera mención y luego glosamos: los falsos amigos ingleses prometen equivalencia con el matrimonio.</p>\n<h3>D. Insight</h3>\n<p><em>Singular</em> significa exclusividad del proyecto conyugal, no “estilo de vida raro”. Traducirlo como “unique lifestyle” es un error típico de traducción automática.</p>"},{"id":"fun-facts","title":"X. Datos y curiosidades","html":"<ol>\n<li>La Ley 54/1990 es anterior a buena parte de la práctica constitucional que amplió protección LGBTQ+; la Corte estiró el estatuto antes de que el Congreso fijara la edad en 2025.</li>\n<li>La Ley 979/2005 se vendió como reforma de “prueba ágil”: notarías y conciliadores, no solo juicios.</li>\n<li>C-075/2007 sigue siendo la cita estrella cuando RR. HH. o bancos preguntan si “cuenta” la pareja del mismo sexo.</li>\n<li>Puede haber UMH <strong>sin</strong> sociedad patrimonial si no corrieron los dos años.</li>\n<li>La muerte de un compañero puede llevar la liquidación al proceso de sucesión — si la prueba de UMH está lista.</li>\n<li>La Ley 2447/2025 empaqueta la edad mínima de UMH con la prohibición de matrimonios tempranos.</li>\n<li>LegalApp del MinJusticia explica en español claro las rutas notarial vs judicial (útil para preparar al cliente, no sustituye la ley).</li>\n</ol>"},{"id":"bibliography","title":"XI. Bibliografía","html":"<ul>\n<li>[Ley · 54/1990 · Vigente con reformas] — Uniones maritales de hecho · ⏱️ ~20 min · 🔗 <a href=\"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=30896\">https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=30896</a></li>\n<li>[Ley · 979/2005 · Vigente] — Mecanismos de declaración · ⏱️ ~15 min · 🔗 <a href=\"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=30898\">https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=30898</a></li>\n<li>[Ley · 2447/2025 · Vigente] — Eliminación de uniones tempranas · ⏱️ ~25 min · 🔗 <a href=\"https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=258236\">https://www.funcionpublica.gov.co/eva/gestornormativo/norma.php?i=258236</a></li>\n<li>[Sentencia · C-075/2007 · Corte Constitucional] — Parejas del mismo sexo · ⏱️ ~50 min · 🔗 <a href=\"https://www.corteconstitucional.gov.co/relatoria/2007/C-075-07.htm\">https://www.corteconstitucional.gov.co/relatoria/2007/C-075-07.htm</a></li>\n<li>[Sentencia · C-151/2023 · Corte Constitucional] — Línea compañero permanente · ⏱️ ~40 min · 🔗 <a href=\"https://www.corteconstitucional.gov.co/relatoria/2023/c-151-23.htm\">https://www.corteconstitucional.gov.co/relatoria/2023/c-151-23.htm</a></li>\n<li>[Guía · MinJusticia LegalApp] — Declarar unión libre · ⏱️ ~10 min · 🔗 <a href=\"https://www.minjusticia.gov.co/programas-co/LegalApp/Paginas/Que-debo-hacer-para-declarar-que-convivo-en-union-libre.aspx\">https://www.minjusticia.gov.co/programas-co/LegalApp/Paginas/Que-debo-hacer-para-declarar-que-convivo-en-union-libre.aspx</a></li>\n</ul>"}]'::jsonb,
